INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wizards-and-warriors-x-fortress-of-fear', 48922, '1990-02-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49ec.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6v66.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizards & Warriors X: Fortress of Fear', 'The incredible saga of Wizards and Warriors continues. As Kuros you''ll enter the dreaded Fortress of Fear in your pursuit of the Evil Wizard, Malkil. Hundreds of enemy encounters await you. Deadly bats and other flying beasts attack from above. Scorching fireballs and arrows speed toward you. And skin crawling spiders and undead skeletons appear from the darkness. Defeat them all! Only those with the blackest of hearts dwell among the 18 levels of challenging game play. But the rewards are great, riches beyond belief, keys to long lost treasure and magic spells and potions. And what better reward could you seek than a final encounter with the Evil Wizard Malkil himself? Beware, Kuros. Others have journeyed into the Fortress of Fear, but none have returned alive.' FROM games WHERE igdb_id = 48922 ON CONFLICT (game_id, language_code) DO NOTHING;
