INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventures in the Magic Kingdom', 'Adventures in the Magic Kingdom is a game developed by Capcon where the player explores various rides in Disney theme parks. The player must complete five different stages, modeled after rides, as well as a trivia quest in order to retrieve the set of keys. Players choose which stage to play by walking around the park in the game''s overworld map.' FROM games WHERE igdb_id = 8130 ON CONFLICT (game_id, language_code) DO NOTHING;
