INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlemaster', '"Battlemaster is a fanatsy aracde adventure set in a world of myth and feudal strife. The land is in decay: isolated villages, towns and castles are divided by areas of chaotic monster-infested wilderness. Your task is to restore order by conquering the four kingdoms and handing their crowns to the Watcher who inhabits the Tower."
