INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Unit Zeoth', 'Battle Unit Zeoth takes place in the future where mankind is invaded by a race of alien robots known as the Grein. The Earth’s forces were triumphant in battle and the Grein forces fled the Solar System. However, as they retreated, the Grein left behind a secret underground base filled with self-replicating Grein machines.
