INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Nemo: The Dream Master', 'Little Nemo: The Dream Master is a platform game that revolves around a young boy in his own surreal dreams as he journeys to Slumberland. Nemo can ride certain animals such as a frog, a gorilla, or a mole, by feeding them candy. Each animal has its own skills needed to complete each level. The purpose of the game is to travel to the Nightmare land to rescue Morpheus, the king of Slumberland, from the clutches of the evil Nightmare King. The game is based on the Japanese animated film, Little Nemo: Adventures in Slumberland, which itself is based on the comic strip Little Nemo in Slumberland.' FROM games WHERE igdb_id = 9160 ON CONFLICT (game_id, language_code) DO NOTHING;
