INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ghostbusters', 4534, '1990-06-29', 10, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4tut.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zddrqg7ihtzrys6uf0ff.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghostbusters', 'Ghostbusters was published by Sega and developed by Compile for the Mega Drive/Genesis on June 29, 1990. It is unrelated to the earlier Activision game (though their name still appears in the copyright screen), and is instead a run and gun game in which the player takes control of squat cartoon representations of three of the four Ghostbusters from the movie, with the noticeable absence of Winston Zeddemore. Four levels are available initially; after they are completed, a fifth level is unlocked, followed by a sixth and final level. Each level contains a number (usually two) of mid-bosses known as "middle ghosts"; after a middle ghost is defeated, it turns into a small green ghost which can be captured for extra money by luring it over a ghost trap. Between levels, money can be used to buy powerups, such as a 3-way shot or recovery items.' FROM games WHERE igdb_id = 4534 ON CONFLICT (game_id, language_code) DO NOTHING;
