INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Gear 2: Solid Snake', 'Metal Gear 2: Solid Snake is an action-adventure stealth video game created and published by Konami for the MSX2 computer platform. Acting as a direct continuation of the MSX2 version of the original Metal Gear, it was written and designed by the series'' creator, Hideo Kojima. Kojima''s inspiration for this game arose as a response to the development of Snake''s Revenge, a separate sequel being produced simultaneously for the NES, intended primarily for the North American and European markets.' FROM games WHERE igdb_id = 377 ON CONFLICT (game_id, language_code) DO NOTHING;
