INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'StarTropics', 'Find out just how resourceful you can be in this classic game, with its mixture of adventure and RPG elements. Step into the shoes of Mike Jones, a teenage star pitcher from Seattle who has come to the tropics to visit his famous archeologist uncle, Dr. Jones. After being told that his uncle has been abducted, Mike begins a perilous quest in order to rescue him and figure out the mysterious plot behind his disappearance.' FROM games WHERE igdb_id = 15901 ON CONFLICT (game_id, language_code) DO NOTHING;
