INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Baron', 'Experience the thrill of flying World War I bi- and triplanes. Defend yourself in spectacular aerial dogfights whilst enemies assault you from all sides. Carry out bombing missions, negotiate enemy AAA fire and outwit your opponents with smart tactical moves. Red Baron Pack offers exciting air-to-air and air-to-ground combat in an age when wooden bi-planes and tri-planes ruled the air.' FROM games WHERE igdb_id = 1934 ON CONFLICT (game_id, language_code) DO NOTHING;
