INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Captain Tsubasa Vol. II: Super Striker', 'Captain Tsubasa Volume II: Super Striker is a continuation of the "Cinematic Soccer" series of soccer games. It''s the direct sequel to Captain Tsubasa and is fairly similar to its predecessor but with some slight graphical improvements. The game features an original new story and original characters, starting after the three-year time skip.' FROM games WHERE igdb_id = 102254 ON CONFLICT (game_id, language_code) DO NOTHING;
