INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario World', 'A 2D platformer and first entry on the SNES in the Super Mario franchise, Super Mario World follows Mario as he attempts to defeat Bowser''s underlings and rescue Princess Peach from his clutches. The game features a save system, a less linear world map, an expanded movement arsenal and numerous new items for Mario, alongside new approaches to level design and art direction.' FROM games WHERE igdb_id = 1070 ON CONFLICT (game_id, language_code) DO NOTHING;
