INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'New Ghostbusters II', '"New Ghostbusters II" is an action video game for the Nintendo Entertainment System developed and published by HAL Laboratory in 1990 in Japan and in 1991 in the PAL region. The NES version was never released in North America due to licensing issues with Activision. As a result, NES players in North America only received Activision''s Ghostbusters II game.' FROM games WHERE igdb_id = 3658 ON CONFLICT (game_id, language_code) DO NOTHING;
