INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digital Devil Story: Megami Tensei II', 'Digital Devil Story: Megami Tensei II is the sequel to Digital Devil Story: Megami Tensei. It was published by Namco in 1990 for the Family Computer and is the second video game in the Megami Tensei series. This is the first game in the series to not be based on the original novels by Aya Nishitani, but it retains much of the gameplay aspects of its predecessor. The music in the game is enhanced by an eight-channel Namco 163 WSG sound chip on the cartridge.' FROM games WHERE igdb_id = 48656 ON CONFLICT (game_id, language_code) DO NOTHING;
