INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizardry: Bane of the Cosmic Forge', 'Ten years ago, Wizardry set the standards in Fantasy Role-Playing (FRP). Now after two million copies have been sold and dozens of awards have been won, Bane of the Cosmic Forge raises and redefines those standards. This new Wizardry , the truest simulation ever of Fantasy Role Playing, will push your computer, your mind, and your sense of adventure to their very limits. Only through the power of the latest computer technology could the full dimensions of this new genre in FRP be possible.' FROM games WHERE igdb_id = 10496 ON CONFLICT (game_id, language_code) DO NOTHING;
