INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LHX: Attack Chopper', 'LHX: Attack Chopper is a helicopter simulation with a strong arcade focus. You can freely choose which missions to fly first, and which helicopter to fly in a given mission. There are a total of four helicopters: Apache, Blackhawk, Osprey and LHX. With this fine selection of death machines you will engage countless enemy targets in Libya, East Germany and Vietnam throughout the game.' FROM games WHERE igdb_id = 2166 ON CONFLICT (game_id, language_code) DO NOTHING;
