INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dick Tracy', 'Dick Tracy is a tie in to the 1990 movie adaptation of the classic comic strip, staring Warren Beatty and Madonna. While an action/adventure hybrid using this license was released by Disney for the PC and Amiga, Titus also held a license to the movie. This is a side scrolling action game, where you control Dick Tracy as he moves through five stages, shooting gangsters with an assortment of weapons. Each stage leads to one of the mob bosses, until you ultimately capture the big man himself.' FROM games WHERE igdb_id = 13058 ON CONFLICT (game_id, language_code) DO NOTHING;
