INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Warrior IV', 'Dragon Warrior IV differs from the rest of the series by breaking up the game into five distinct chapters, each of which focuses on a different protagonist or protagonists. The first four are told from the perspective of the Hero''s future companions and the fifth one, from the hero''s perspective, brings all the characters together as they begin their journey to save the world.' FROM games WHERE igdb_id = 16584 ON CONFLICT (game_id, language_code) DO NOTHING;
