INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('teenage-mutant-ninja-turtles-fall-of-the-foot-clan', 48928, '1990-08-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dox.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar84b.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles: Fall of the Foot Clan', 'In cahoots with exiled alien zap master Krang, the evil Shredder has once again kidnapped the dashing damsel of the news desk, April O''Neil. To rescue this ravishing reporter, you must return to the sewers and dredge forth those reptiles with a penchant for pizza and all the nifty knifework of a chop suey chef. You''ll control every move of Leonardo, Michaelangelo, Donatello and Raphael as they arm themselves with head-rattling Nunchakus, back-stabbing Sai Swords, and liver-lashing Katana Blades. Of course, this once in a light year adventure will really start rumbling the nanosecond you bust into 5 never-before-seen levels of Manhattan mayhem, including the Traffic Jam, Waste Dump Ravine and Technodrome Tower. Here you''ll perfect the ancient art of icing, dicing and shuriken-slicing. And you''ll get the chance to wipe the smirks off the faces of all-new creepshow freaks like Roadkill Rodney, Shell Shocker and that nasty villain Filet O''Filth. So get back into your shell and start snapping away, before April goes from delivering the news to singing the blues in some new cement shoes.' FROM games WHERE igdb_id = 48928 ON CONFLICT (game_id, language_code) DO NOTHING;
