INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Emblem: Ankoku Ryuu to Hikari no Tsurugi', 'Fire Emblem: The Dark Dragon and Sword of Light is the first game in the Fire Emblem series, developed by Intelligent Systems and published by Nintendo. It was first released on the Famicom (known internationally as the Nintendo Entertainment System) on April 20, 1990. It takes place on the continent of Archanea. It stars Marth, a character who later appeared in Super Smash Bros. Melee.
