INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Chip ''n Dale Rescue Rangers', 'Chip ''n Dale Rescue Rangers is a platformer video game developed and published by Capcom based on the Disney animated series of the same name. Originally released for the Nintendo Entertainment System in Japan and North America in 1990, it came to Europe the next year, and was ported to the Nintendo PlayChoice-10 arcade system. It sold approximately 1.2 million copies worldwide.' FROM games WHERE igdb_id = 6490 ON CONFLICT (game_id, language_code) DO NOTHING;
