INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shove-it-the-warehouse-game', 4375, '1990-01-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8hg9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scn4vn.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shove It! The Warehouse Game', 'You''ll need brains and brawn to solve these mind bending puzzles. You''re Stevedore the warehouse man. You shove boxes for a living. This morning you met the girl of your dreams, but to get to her you''ll need the car of your dreams! And that means working overtime and using your head. Now you''ve got a big job ahead of you, 16 levels, 160 warehouses that need to have their boxes shoved into order. Each room is a puzzle that takes skill, strategy and your wits to solve. As you progress, the ware-houses get harder. It''s addictive! Once you start you can''t stop. Some warehouses may seem impossible, but there is a solution to each one. To help you there is a "trace mode" to retrace your steps and passwords to access each level, once you''ve earned that level. You can even design your own warehouses to stump your friends. If you can beat all 16 levels, a brand new sports car... and the girl... will be yours. Fall and you''ll be yelling Shove It!' FROM games WHERE igdb_id = 4375 ON CONFLICT (game_id, language_code) DO NOTHING;
