INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Todd''s Adventures in Slime World', 'You are Todd, the explorer of new worlds. It''s your adventure to travel deep into Slime World, the gooiest, drippiest place around. There are scary blobs to shoot and lots of objects and weapons to find. "Link up" with up to seven of your fellow slimers for an awesome multiplayer adventure.' FROM games WHERE igdb_id = 4543 ON CONFLICT (game_id, language_code) DO NOTHING;
