INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Amazing Spider-Man', 'The Amazing Spider-Man is a side-scrolling action game. Spider-Man can use his web making abilities to either hang from the ceiling or shoot webs out like bullets, but most of his attacks are punches or kicks. Also included are two vertical-scrolling building climbing segments in which Spider-Man has to avoid enemies and falling objects which try to knock him down. His spider sense rings a few moments earlier so you have enough time to react.' FROM games WHERE igdb_id = 83898 ON CONFLICT (game_id, language_code) DO NOTHING;
