INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil''s Crush', 'Devil''s Crush (known as Devil Crash in Japan) is a pinball video game developed by NAXAT Soft for the TurboGrafx-16 and released in 1990. The second installment in the Crush Pinball series after Alien Crush, the game has an eerie occult theme with skulls, skeletons, and demons. It was later followed by Jaki Crush and Alien Crush Returns.
