INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Valis III', 'After Yuko has defeated the evil Rogles, peace descended upon Earth and the magical world of Vecanti. But a new threat has arisen: an enigmatic man named Glames from the Dark World, possessor of a sword named Leethus, is planning to conquer both Earth and Vecanti, convinced that there is no other way to save his world from imminent destruction. A young girl from the Dark World named Cham escapes from Glames, and asks Yuko to help her stop him with the aid of her Valis sword.
