INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('king-s-quest-v-absence-makes-the-heart-go-yonder', 2238, '1990-11-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28rv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvc5.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King''s Quest V: Absence Makes the Heart Go Yonder!', 'King''s Quest V: Absence Makes the Heart Go Yonder is an adventure game in the long-running King''s Quest series. Players control King Graham as he embarks on a quest to rescue the Royal Family of Daventry, who have mysteriously disappeared. The game takes place in a fantasy world filled with magic and peril, where Graham must overcome obstacles and solve puzzles to progress. As the fifth installment in the series created by Roberta Williams, King''s Quest V builds upon the graphical adventure game format that Williams pioneered, combining text and visuals to create an immersive storytelling experience. The game continues the legacy of the King''s Quest series, which had become a popular and influential franchise in the computer gaming industry by the time of its release.' FROM games WHERE igdb_id = 2238 ON CONFLICT (game_id, language_code) DO NOTHING;
