INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Champions of Krynn', 'Even after the good Dragonarmies defeated the evil Dragonarmies in the War of the Lance, there are still pockets of Evil left on the continent of Ansalon, which is located on the world of Krynn. Rampaging through the lands surrounding the cities which are still used as bases of power by the forces of Evil, the characters will uncover a plot by the Aurak Draconian Myrtani to lure the good armies into a trap and wipe them out.' FROM games WHERE igdb_id = 2456 ON CONFLICT (game_id, language_code) DO NOTHING;
