INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gunboat-river-combat-simulation', 12127, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5tqz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvlq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gunboat: River Combat Simulation', 'Gunboat is a 3D action simulation of River patrol U.S. Gunboat. Your Gunboat carries a crew of four men. A first-class petty officer who serves as boat captain and pilot. A gunner’s mate, who controls the forward guns. An engine man, who takes care of the engines and serves as midship gunner and a seaman who controls the guns.' FROM games WHERE igdb_id = 12127 ON CONFLICT (game_id, language_code) DO NOTHING;
