INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rolan''s Curse', 'After centuries in captivity, King Barius, Lord of the Demons, has escaped. In his fury he has cursed the peaceful land of Rolan. Hordes of dark creatures roam free in the countryside. A desperate cry goes out... are there any warriors brave enough to free the people from the curse?' FROM games WHERE igdb_id = 49023 ON CONFLICT (game_id, language_code) DO NOTHING;
