INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-stations', 20136, '1990-12-31', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ifhxsi0bemdx7lgwsnfh.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Stations', 'Battlestations is a title where you take control of your own fleet, ranging from patrol boats and mine layers to battleships and aircraft carriers. You''ll get to pick any of the ten missions right away, all of which have a different challenge to encounter, like protecting your base from troop transports, and a mission where you''ll have to prevent poachers from killing whales. You''ll also get to pick from five commanders to fight against, all of which have stereotypical strengths and weaknesses. Afterwards, you''ll go right to the mission, where you''ll be able to navigate your ship silhouettes on a 2D, radar-esque map.' FROM games WHERE igdb_id = 20136 ON CONFLICT (game_id, language_code) DO NOTHING;
