INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'John Madden Football', 'Game play modes include regular season, playoffs and sudden death. The game features 16 regular teams plus one All-Madden team, each with their own strengths and weaknesses. Play actions include selecting a pass recipient as a play unfolds, block tackles, dives and sackings. Different weather conditions come into play when it''s wet, snowy or muddy.' FROM games WHERE igdb_id = 4400 ON CONFLICT (game_id, language_code) DO NOTHING;
