INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Commander Keen: Invasion of the Vorticons', 'This is the retail version of the original Commander Keen trilogy. You play the role of Billy Blaze, an 8-year old superkid who dons his brother''s football helmet and becomes Commander Keen - Defender of the Earth. This trilogy is comprised of the episodes: Marooned on Mars, The Earth Explodes and Keen Must Die!
