INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hit the Ice: The Video Hockey League', 'This radical hockey game pits you and your team against some of the toughest skaters ever to burn a hole in the ice! Victory goes to the team that kicks, punches, and high-sticks its opponent into slush. Standard hockey rules apply, plus a few surprises to stir things up. So lace on your skates and fasten your face mask - hockey is about to break loose!' FROM games WHERE igdb_id = 46208 ON CONFLICT (game_id, language_code) DO NOTHING;
