INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('captain-skyhawk', 48071, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6v2p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hexaxcg2pmosc8tnkhud.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Captain Skyhawk', 'The player takes a role of a fighter pilot working to repel an alien invasion. Aliens have invaded Earth, and have built four land bases. These bases are designed to drain Earth''s energy and feed it to their mother space station. If the space station is allowed to obtain enough energy, it will destroy the Earth with a massive laser blast. The player must destroy the enemy bases, then go after the space station itself. Scientists, during the course of the game, are working on a top-secret Neutron Cannon. During several missions, the player must make supply drops to the scientists working underground. Sometimes, the aliens will have a scientist captive. Then the player must defeat the alien base and take the scientist to safety.' FROM games WHERE igdb_id = 48071 ON CONFLICT (game_id, language_code) DO NOTHING;
