INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Code Name: Viper', 'The player takes the role of Kenny Smith, an agent of the 98th Special Forces, also known as "Code Name: Viper", who is assigned by his commander, Director Jones, to investigate a large drug syndicate that covers all of South America. Smith''s objective is to rescue a missing Viper agent in each of the syndicate''s seven hideouts and uncover clues of the Syndicate''s true mastermind.' FROM games WHERE igdb_id = 48069 ON CONFLICT (game_id, language_code) DO NOTHING;
