INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PGA Tour Golf', 'This first game in the series was originally released in 1990 for DOS computers, 1991 for Sega Genesis, Macintosh, SNES, and Commodore Amiga, and 1993 for Sega Master System and Game Gear. It was developed and published by Electronic Arts for DOS and Macintosh, ported to Genesis, SNES, and Game Gear by Sterling Silver Software, to Amiga by Bluesky Innovations, and to Master System by Polygon Games. The Genesis/Mega Drive version features 6 professional golfers as playable or as CPU opponents; Fred Couples, Mark McCumber, Larry Mize, Joey Sindelar, Craig Stadler, Bruce Lietzke.' FROM games WHERE igdb_id = 12714 ON CONFLICT (game_id, language_code) DO NOTHING;
