INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rampart', 'Rampart is a game combining strategy and artillery action. Build your castle from Tetris-style pieces, place your cannons, bombard the enemy, try to repair, do it all over again. The original arcade release has a single-player and a two-player mode; later revisions incorporate three-player gameplay.' FROM games WHERE igdb_id = 9684 ON CONFLICT (game_id, language_code) DO NOTHING;
