INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Klax', 'Klax is a 1989 computer puzzle game designed by Dave Akers and Mark Stephen Pierce. The object is to line up colored blocks into rows of similar colors to make them disappear, to which the object of Columns is similar. Atari Games originally released it as a coin-op follow up to Tetris, about which they were tangled in a legal dispute at the time.' FROM games WHERE igdb_id = 4484 ON CONFLICT (game_id, language_code) DO NOTHING;
