INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spot: The Video Game', 'A puzzle game loosely featuring licensing from the 7Up soft drink. The gameplay involves up to 4 players, which can be either human or computer, each taking on spots of a particular colour. Starting from opposite corners, they take it in turns to move, either by ''reproducing'' one of their spots to form another one in an adjacent square, or by making a jump, losing the square you did have but taking one two spaces away.' FROM games WHERE igdb_id = 48075 ON CONFLICT (game_id, language_code) DO NOTHING;
