INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turrican', 'Turrican is a 1990 video game programmed and designed by Manfred Trenz. It was first developed for the Commodore 64 by Rainbow Arts, but was ported to other systems later. In addition to concept design and character creation, Trenz personally programmed Turrican on the Commodore 64. A sequel, Turrican II, followed 1991 for the Commodore 64 and other platforms.' FROM games WHERE igdb_id = 5164 ON CONFLICT (game_id, language_code) DO NOTHING;
