INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snake''s Revenge', 'Snake''s Revenge is a stealth action-adventure game developed by Konami for the Nintendo Entertainment System. Serving as a standalone sequel to Metal Gear, it was released in North America and the PAL region, capitalising on the international success of the NES version. Notably, this instalment was created without the involvement of series creator Hideo Kojima. Meanwhile, Kojima went on to develop a separate sequel for the MSX2 titled Metal Gear 2: Solid Snake, which debuted later in the same year in Japan.' FROM games WHERE igdb_id = 7848 ON CONFLICT (game_id, language_code) DO NOTHING;
