INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultima VI: The False Prophet', 'Ultima VI sees the player return to Britannia, at war with a race of gargoyles from another land, struggling to stop a prophecy from ending their race. The player must help defend Britannia against these gargoyles, and ultimately discover the secrets about both lands and its peoples.' FROM games WHERE igdb_id = 12230 ON CONFLICT (game_id, language_code) DO NOTHING;
