INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles II: The Arcade Game', 'This version includes two new levels (the first part of Scene 3 and all of Scene 6), which feature new enemy characters, including two new bosses: Tora (a dog-like "blizzard beast") and Shogun (a robotic samurai), both characters created for the game. Most of the original stages from the arcade version were extended as well and the second half of Scene 3, the parking garage stage, replaces the arcade version''s end battle with Bebop and Rocksteady with a battle against the mutated fly form of Baxter Stockman.' FROM games WHERE igdb_id = 3816 ON CONFLICT (game_id, language_code) DO NOTHING;
